"""Build visual specimens for every proposed product component and its options."""
from pathlib import Path
import re,json,html
R=Path(__file__).resolve().parent
template=(R/'atlas-template.html').read_text(encoding='utf8')
css=template.split('<style>')[1].split('</style>')[0]
models=[]
for line in (R/'components.md').read_text(encoding='utf8').splitlines():
 m=re.match(r'^\| (C\d\d) (.+?) \|',line)
 if m:
  cells=[v.strip() for v in line.strip('|').split('|')]
  models.append(dict(id=m[1],name=m[2],anatomy=cells[1],options=cells[2],failure=cells[3]))
assert len(models)==40
def button(v,cls='primary',disabled=False):return f'<button class="{cls}" {"disabled" if disabled else ""}>{v}</button>'
def actions(*v):return '<div class="screen-actions">'+''.join(button(x) for x in v)+'</div>'
def row(label,value):return f'<div class="row"><span class="item-label">{label}</span><span class="item-value">{value}</span></div>'
def field(label,value='',error=False):return f'<div class="field"><label>{label}<input value="{value}" placeholder="Safe synthetic draft"></label>'+('<p class="validation-error">Review the actual field constraint.</p>' if error else '<p class="help">Persistent label and contextual guidance.</p>')+'</div>'
def badge(v,cls=''):return f'<span class="badge {cls}">{v}</span>'
def choice(v,checked=False):return f'<label class="choice-row"><input type="radio" name="single-choice" {"checked" if checked else ""}><span>{v}</span></label>'
DEMO={
'C01':'<div class="screen-actions">'+button('Request taxi')+button('Review details','secondary')+button('Back','tertiary')+button('Cancel request','danger')+button('Requesting…','primary',True)+button('Unavailable · offline','secondary',True)+'</div>',
'C02':'<div class="iconset">'+''.join(f'<button class="backicon" aria-label="{l}">{v}</button><small>{l}</small>' for l,v in [('Back','‹'),('Refresh','↻'),('Inbox · 3 unread','3'),('Safety','◇')])+'</div>',
'C03':field('Email or phone')+field('Destination label','Central square')+field('Review reason','',True)+'<label class="field">Password<input type="password" placeholder="Never enter real credentials"></label>',
'C04':choice('Cash · always available',True)+choice('Manual transfer · only if enabled')+'<label class="choice-row"><input type="checkbox"><span>Reviewed exact target and consequence</span></label><fieldset><legend>Style · local presentation</legend>'+''.join(f'<label class="choice-row"><input type="radio" name="style-demo" data-style-demo="{v}"><span>{name}</span></label>' for v,name in [('fold','Folded Streets'),('print','Street Press'),('tactile','Glazed Machine'),('notepad','Notepad')])+'</fieldset>',
'C05':'<div class="segments"><button class="picked">Now</button><button>Later · enabled policy</button></div><div class="segments"><button>English</button><button>Français</button><button class="picked">العربية</button></div>',
'C06':'<header class="screen-top"><button class="backicon">‹</button><h3>Review your trip</h3><button class="backicon" aria-label="Help">?</button></header>',
'C07':'<nav class="screen-nav"><span>↗<br>Ride</span><span>◷<br>Trips</span><span>○<br>Account</span></nav><nav class="screen-nav"><span>↗<br>Work</span><span>▤<br>Earnings</span><span>○<br>Account</span></nav>',
'C08':'<div class="sheet-spec"><div class="handle"></div><h3>Review your trip</h3>'+row('Pickup','Central square')+row('Destination','Seafront')+actions('Request taxi')+'</div>',
'C09':'<div class="block journey">'+row('A · Pickup','Central square · confirmed point')+row('B · Destination','Seafront · confirmed point')+'</div>',
'C10':'<div class="pin-spec"><span>●</span><p>Move the map to choose pickup</p></div>'+row('Selected place','Confirmed map point')+actions('Confirm pickup'),
'C11':'<div class="block money">'+row('Estimated fare','35 MAD')+'</div>'+row('Quote validity','Actual server expiry')+row('Unavailable','Refresh the fare before requesting'),
'C12':'<div class="identity-sample"><span class="avatar">S</span><div><b>Samir · assigned taxi</b><p>White sedan · TX 1248</p><small>Check the taxi identifier at pickup</small></div></div>',
'C13':'<div class="block timer">'+row('Time to respond','00:24 · server time')+'</div><div class="block journey">'+row('Pickup','Central square')+row('Destination','Seafront')+'</div>'+row('Fare / fee / expected net','35 / 3 / 32 MAD · synthetic')+actions('Accept','Decline'),
'C14':row('Confirmed phase','At pickup')+row('Next permitted command','Start trip')+'<div class="notice block">Uncertain phase: refresh before a lifecycle command.</div>'+actions('Start trip'),
'C15':row('Current availability','Offline')+'<div class="screen-actions">'+button('Go online')+button('Going online…','primary',True)+'</div><p class="help">Online appears only after confirmation and fresh eligibility/location.</p>',
'C16':'<div class="health"><b>Location needs attention</b><p>Observation is too old for online work.</p><button>Review settings</button></div>',
'C17':''.join(badge(v,c) for v,c in [('○ Draft',''),('◷ Pending','warning'),('✓ Confirmed','success'),('! Failed','danger'),('◇ Restricted','')]),
'C18':'<div class="block notice"><h4>Connection interrupted</h4><p>Last confirmed trip remains available.</p><button>Refresh this trip</button></div>',
'C19':'<div role="status" aria-label="Loading record specimen"><div class="skeletonline"></div><div class="skeletonline short"></div><div class="skeletonline"></div><small>Loading the selected record</small></div>',
'C20':row('Trip · today 14:20','Central square → Seafront')+row('Amount / payment','35 MAD · CASH PENDING')+actions('Review cash confirmation'),
'C21':'<div class="block money">'+row('Final fare','35 MAD')+'</div>'+row('Method','Cash')+row('Payment','Not yet confirmed')+row('Refund','Actual confirmed returned-money ledger only'),
'C22':'<h3>Confirm cash received?</h3>'+row('Exact trip / amount','Selected completed trip · 35 MAD')+'<p>Record only the actual handover.</p><div class="screen-actions">'+button('Confirm received')+button('Cancel','secondary')+'</div>',
'C23':'<h3>Vehicle identity</h3><p class="help">One related group at a time.</p>'+field('Make')+field('Model')+field('Registration plate'),
'C24':'<div class="timeline"><div class="items">'+row('Submitted · recorded date','Application received')+row('Under review · recorded date','Current state')+row('Authorization','Not yet issued')+'</div></div>',
'C25':row('Central square → Seafront','Today · Completed · 35 MAD')+row('Airport → Central square','Yesterday · Cancelled · actual status'),
'C26':'<div class="records">'+row('● Application update','Today · Unread · open authorized application')+row('○ Trip update','Yesterday · Read · refresh authoritative trip')+'</div>',
'C27':choice('Ride problem',True)+choice('Payment problem')+choice('Account access')+choice('Other')+field('Subject')+field('Description')+actions('Create support case'),
'C28':row('Language','English / Français / العربية')+row('Style','Folded Streets / Street Press / Glazed Machine / Notepad')+row('Security','Sessions / Password / Recovery codes'),
'C29':'<div class="documents">'+row('Professional document','Required · PDF / JPEG / PNG when delivered')+row('File status','Clean / pending scan / rejected are distinct')+'</div><button>Choose allowed file</button>',
'C30':'<div class="scope"><b>Market · Morocco</b><span>City · Casablanca</span><span>Operator Alpha</span><span>Actual freshness</span></div>',
'C31':'<div class="table"><div class="items">'+row('Application A','City · Under review · submitted date')+row('Application B','City · Submitted · submitted date')+'</div></div><p class="help">Actual loaded / total · supported pagination</p>',
'C32':'<div class="master-sample"><div class="block"><h4>Queue</h4>'+row('Selected record','Under review')+'</div><div class="block"><h4>Record detail</h4>'+row('Scope / version','Exact city · revision')+actions('Review permitted action')+'</div></div>',
'C33':row('State','Draft · immutable version')+field('Effective from','ISO timestamp with zone')+choice('Compatible loaded record',True)+'<div class="notice block">Conflict reloads the exact version before a new review.</div>',
'C34':'<div class="chartbars" aria-label="Synthetic aggregate specimen"><span style="height:30%"></span><span style="height:70%"></span><span style="height:55%"></span></div>'+row('Unit / time / freshness','Aggregate only · labelled window')+row('Suppression','Small-cell privacy threshold; no individual trails'),
'C35':row('Reviewed action · recorded time','Authorized actor · exact scope')+row('Safe reference','Expand approved reference; no private payload'),
'C36':field('Find authorized destination')+'<div class="records">'+row('Driver applications','Navigation · permitted scope')+row('Support cases','Navigation · permitted scope')+'</div><small>Navigation only · keyboard + visible menu</small>',
'C37':'<button id="copy-demo">Copy synthetic reference</button><p id="copy-result" role="status">Fixed icon / text geometry</p>',
'C38':'<div class="screen-actions">'+button('↻ Refresh')+button('↻ Refreshing…','secondary',True)+'</div><p class="help">Obsolete scope/session reads are fenced.</p>',
'C39':'<h3>No past trips yet</h3><p>Your completed trips will appear here.</p>'+actions('Plan a trip')+'<p class="help">Failed, restricted and filtered queries have different explanations.</p>',
'C40':'<div style="min-height:120px"><h3>Reviewed task content</h3><p>Terms remain visible above the footer.</p></div><div class="screen-actions">'+button('Confirm reviewed action')+button('Cancel','secondary')+'</div>'}
assert set(DEMO)=={p['id'] for p in models}
data=json.dumps(models,ensure_ascii=False).replace('<','\\u003c')
extra='.componentgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:24px;padding:28px}.componentgrid article{min-width:0;background:white;border:1px solid #a8b1a8;border-radius:16px;padding:18px}.componentgrid h2{font-size:20px;margin:8px 0}.componentgrid p{font-size:13px;margin:10px 0;color:#526158}.componentgrid .atlas-screen{border-radius:14px;padding:16px;max-width:none;margin:18px 0}.componentgrid .atlas-screen p{color:var(--secondary)}.componentgrid .screen-actions{padding:10px 0}.componentgrid .field{margin:14px 0}.componentgrid small{font-size:.75em}.badge{display:inline-flex;padding:6px 10px;border-radius:8px;background:var(--wash);margin:5px;font-size:.75em;color:var(--ink);border:1px solid var(--stroke)}.badge.warning{background:#fff0cf;color:#805000}.badge.success{background:#d5f3dc;color:#14562f}.badge.danger{background:#ffe0de;color:#962e30}.screen-actions .danger{background:#a9272a;color:white;border-color:#a9272a}.screen-actions .tertiary{border:0;background:transparent;text-decoration:underline}.screen-actions button:disabled{opacity:.6}.segments,.iconset{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0}.segments button,.health button,.componentgrid .atlas-screen>button{border:1px solid var(--stroke);border-radius:10px;background:var(--surface);color:var(--ink);padding:10px;min-height:48px}.segments .picked{background:var(--wash);border-color:var(--action)}.sheet-spec{border:1px solid var(--stroke);border-radius:24px 24px 0 0;padding:16px}.handle{width:32px;height:4px;background:var(--stroke);border-radius:3px;margin:0 auto 16px}.pin-spec{background:#e4ebe3;text-align:center;padding:28px;color:#25382f;border-radius:12px}.pin-spec span{font-size:48px;color:var(--action)}.identity-sample{display:flex;gap:14px;align-items:center}.avatar{min-width:48px;height:48px;display:grid;place-items:center;background:var(--wash);border-radius:14px}.health{border:1px solid var(--stroke);padding:16px;border-radius:12px;background:var(--wash)}.master-sample{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:700px){.componentgrid{padding:16px}.master-sample{grid-template-columns:1fr}}'
def demo_for(p):return DEMO[p['id']].replace('name="single-choice"',f'name="single-choice-{p["id"]}"')
cards=''.join(f'<article id="{p["id"]}"><div class="eyebrow">{p["id"]}</div><h2>{html.escape(p["name"])}</h2><p>{html.escape(p["anatomy"])}</p><div class="atlas-screen">{demo_for(p)}</div><b>Every specified option</b><p>{html.escape(p["options"])}</p><b>Failure / access contract</b><p>{html.escape(p["failure"])}</p><p>Normal / focus / pressed / busy / disabled / error / RTL / enlarged text / reduced motion; desktop hover and keyboard. Exact tokens in visual-system.md.</p></article>' for p in models)
pal=re.search(r'const PAL=.*?;\nconst TYPES=.*?;',template,re.S)[0]
js=pal+"\nfunction render(){document.body.dataset.grammar=document.getElementById('palette').value;document.querySelectorAll('input[data-style-demo]').forEach(e=>e.checked=e.dataset.styleDemo===document.getElementById('palette').value);const p=PAL[document.getElementById('palette').value],type=TYPES[document.getElementById('type').value],ar=document.getElementById('locale').value==='ar';document.querySelectorAll('.atlas-screen').forEach(e=>{e.setAttribute('dir',ar?'rtl':'ltr');e.style.cssText=Object.entries(p).map(([k,v])=>'--'+k+':'+v).join(';')+';--surface:'+p.surface+';--font:'+type[ar?1:0]+';--scale:'+document.getElementById('scale').value})}['palette','type','locale','scale'].forEach(id=>document.getElementById(id).addEventListener('change',render));render();document.querySelectorAll('input[data-style-demo]').forEach(e=>e.addEventListener('change',()=>{document.getElementById('palette').value=e.dataset.styleDemo;render()}));document.getElementById('copy-demo').onclick=()=>{document.getElementById('copy-result').textContent='Copied-state specimen · SYNTHETIC-TX-1248 · no actual clipboard operation'};"
controls='<div class="filters"><label>User style<select id="palette">'+''.join(f'<option value="{v}">{name}</option>' for v,name in [('fold','Folded Streets'),('print','Street Press'),('tactile','Glazed Machine'),('notepad','Notepad')])+'</select></label><label>Type<select id="type"><option value="t1">Inter / Noto</option><option value="t2">Jakarta / Noto</option><option value="t3">Plex / Plex Arabic</option></select></label><label>Direction<select id="locale"><option value="en">LTR · English</option><option value="ar">RTL · draft</option></select></label><label>Text scale<select id="scale"><option value="1">100%</option><option value="1.6">160%</option><option value="2">200%</option></select></label></div>'
out='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TaxiMobile · 40 component specimens</title><style>'+css+extra+'.componentgrid article>p{overflow-wrap:anywhere}</style></head><body><header class="masthead"><div class="eyebrow">SELECTED FOUR STYLES · COMPONENT SPECIMENS</div><h1>Every component and its options.</h1><p>40 separately composed specimens. Compare shape, hierarchy, selection, loading and semantic states; the full contracts below each specimen specify the remaining variants. All examples are synthetic and perform no application command.</p><nav class="links"><a href="page-atlas.html">Every page atlas</a><a href="components.md">Exact contracts and Unlumen mapping</a><a href="visual-system.md">Exact tokens</a></nav></header>'+controls+'<main class="componentgrid">'+cards+'</main><script>'+js+'</script></body></html>'
(R/'component-gallery.html').write_text(out,encoding='utf8')
print('40 explicit component specimens; no fallback templates.')
